//
// Menu bar images for every `StatusIconState` (PRD-R10): Pa's KV mark from the asset catalog. CLR-R7 source:
// Pa's own artwork assets/keyvi_menubar_*.svg; the image sets, including the derived states, are generated by
// scripts/make-app-icon.py. No artwork is drawn in this file.
//
// The images are not templates, so the emerald dot keeps its colour. Each image set holds light, dark and
// high-contrast variants. AppKit resolves a catalog image when it draws, with the drawing view's effective
// appearance, so the status button shows the variant of the menu bar it sits on (light or dark mode, a dark or
// tinted wallpaper under a translucent menu bar, Increase Contrast) and redraws when that appearance changes.

import AppKit
import ShellCore

@MainActor
enum StatusGlyph {
    /// Menu bar extra size in points: the artwork's 22 x 22 viewBox.
    static let size = NSSize(width: 22, height: 22)

    /// The catalog image of `state`. A missing image set is a build error (`StatusPresentationTests` checks the
    /// catalog); the template keyboard symbol only keeps the status item visible (PRD-R9) while the accessibility
    /// label still names the state.
    static func image(for state: StatusIconState) -> NSImage {
        if let image = NSImage(named: state.imageName) { return image }
        let fallback = NSImage(systemSymbolName: "keyboard", accessibilityDescription: nil) ?? NSImage(size: size)
        fallback.isTemplate = true
        return fallback
    }
}
